window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["gcp"]=[{"id":"gcp-f0001","card":"q-gcp-001-overview","sec":"gcp-s001","q":"Which stack is used in the GCP Essential Training for Developers course?","a":"<p>Google App Engine with Node.js (Express), Cloud SQL (MySQL), Cloud Storage, Cloud Tasks, Cloud Scheduler, and Cloud Logging, Debugger and Trace.</p>","hand":true},{"id":"gcp-f0002","card":"q-gcp-001-overview","sec":"gcp-s001","q":"Which three products make up the operations tooling in the GCP course stack?","a":"<p>Cloud Logging, Cloud Debugger and Cloud Trace.</p>","hand":true},{"id":"gcp-f0003","card":"q-gcp-002-1-intro-and-core-ideas","sec":"gcp-s002","q":"Who is the GCP Essential Training course aimed at, and what do they need to know?","a":"<p>Developers who have built web apps (Node.js examples) and know basic SQL connectivity. CI/CD knowledge is only needed conceptually.</p>","hand":true},{"id":"gcp-f0004","card":"q-gcp-002-1-intro-and-core-ideas","sec":"gcp-s002","q":"What is traffic splitting in App Engine?","a":"<p>It lets you switch between app versions without downtime.</p>","hand":true},{"id":"gcp-f0005","card":"q-gcp-002-1-intro-and-core-ideas","sec":"gcp-s002","q":"What is object lifecycle management in Cloud Storage?","a":"<p>Automatic deletion or storage-class downgrade of files, based on conditions.</p>","hand":true},{"id":"gcp-f0006","card":"q-gcp-002-1-intro-and-core-ideas","sec":"gcp-s002","q":"What do App Engine and Cloud Tasks achieve together?","a":"<p>They let you scale server capacity up and down for large workloads.</p>","hand":true},{"id":"gcp-f0007","card":"q-gcp-003-project-setup","sec":"gcp-s003","q":"What are the steps to set up a GCP project in the Cloud Console?","a":"<ol>\n  <li>Sign in to the Cloud Console.</li>\n  <li>Create a billing account (a free trial is offered).</li>\n  <li>Create a project from the top nav bar.</li>\n</ol>","hand":true},{"id":"gcp-f0008","card":"q-gcp-003-project-setup","sec":"gcp-s003","q":"What is a GCP Project ID?","a":"<p>A globally unique ID that GCP assigns to the project next to its name. It is used in URLs and config.</p>","hand":true},{"id":"gcp-f0009","card":"q-gcp-003-project-setup","sec":"gcp-s003","q":"Which project settings can stay at their defaults when creating a project?","a":"<p>Organization and location.</p>","hand":true},{"id":"gcp-f0010","card":"q-gcp-004-console-dashboard-cards","sec":"gcp-s004","q":"What do the Project Info and Resources dashboard cards show in the GCP console?","a":"<p>Project Info shows the name, ID, project number and add people/settings. Resources shows the resources the project uses.</p>","hand":true},{"id":"gcp-f0011","card":"q-gcp-004-console-dashboard-cards","sec":"gcp-s004","q":"What does the Trace dashboard card show?","a":"<p>High-latency requests (from Stackdriver).</p>","hand":true},{"id":"gcp-f0012","card":"q-gcp-004-console-dashboard-cards","sec":"gcp-s004","q":"What do the Service Charts and Cloud Status dashboard cards show?","a":"<p>Service Charts shows charts for active services (App Engine, Compute Engine, SQL, APIs). Cloud Status is the Google Cloud uptime dashboard.</p>","hand":true},{"id":"gcp-f0013","card":"q-gcp-004-console-dashboard-cards","sec":"gcp-s004","q":"What do the Billing and Error Reporting dashboard cards show?","a":"<p>Billing shows estimated charges for the billing account. Error Reporting shows the top errors in the past 24 hours.</p>","hand":true},{"id":"gcp-f0014","card":"q-gcp-004-console-dashboard-cards","sec":"gcp-s004","q":"How do you navigate the GCP console?","a":"<p>The dashboard is customizable. Products are reached via the hamburger menu (can be pinned). The resource switcher moves between organizations, projects and folders and opens IAM and org policies. The search bar finds projects, services and items inside services.</p>","hand":true},{"id":"gcp-f0015","card":"q-gcp-005-cloud-shell","sec":"gcp-s005","q":"What is Google Cloud Shell and what resources does it have?","a":"<p>A browser-based Linux terminal on a VM. It has about 5 GB storage, 1.7 GB RAM and 0.5 vCPU. It is free, and specs can be temporarily boosted.</p>","hand":true},{"id":"gcp-f0016","card":"q-gcp-005-cloud-shell","sec":"gcp-s005","q":"What comes pre-configured in Cloud Shell?","a":"<p>Project credentials, the latest gcloud, PHP/Python/Node.js, and Docker and Kubernetes tools. It also includes Vim and a built-in editor.</p>","hand":true},{"id":"gcp-f0017","card":"q-gcp-005-cloud-shell","sec":"gcp-s005","q":"What is Web Preview in Cloud Shell and how do you test it?","a":"<p>It exposes a Cloud Shell port, either Preview on port 8080 or Change port. Start a server on that port, for example:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>python3 -m http.server 8080</code></pre></div>","hand":true},{"id":"gcp-f0018","card":"q-gcp-006-installing-and-initializing-the-cloud-sd","sec":"gcp-s006","q":"What commands install the Cloud SDK, restart the shell and initialize gcloud?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>curl https://sdk.cloud.google.com | bash\nexec -l $SHELL\ngcloud init</code></pre></div>","hand":true},{"id":"gcp-f0019","card":"q-gcp-006-installing-and-initializing-the-cloud-sd","sec":"gcp-s006","q":"What are the steps of <code>gcloud init</code>?","a":"<p>Use \"new settings\", authenticate in the browser, pick a project, and pick a default region/zone (closest to users for low latency).</p>","hand":true},{"id":"gcp-f0020","card":"q-gcp-006-installing-and-initializing-the-cloud-sd","sec":"gcp-s006","q":"Why choose the closest default region/zone in <code>gcloud init</code>?","a":"<p>For low latency to your users.</p>","hand":true},{"id":"gcp-f0021","card":"q-gcp-007-three-cli-tools","sec":"gcp-s007","q":"Which three CLI tools does Google Cloud provide and what is each for?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Tool</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td><strong>gsutil</strong></td><td>Cloud Storage</td></tr>\n      <tr><td><strong>bq</strong></td><td>BigQuery</td></tr>\n      <tr><td><strong>gcloud</strong></td><td>Everything else</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0022","card":"q-gcp-007-three-cli-tools","sec":"gcp-s007","q":"Which CLI do you use for Cloud Storage, and which for BigQuery?","a":"<p><code>gsutil</code> for Cloud Storage and <code>bq</code> for BigQuery.</p>","hand":true},{"id":"gcp-f0023","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"What are the main gcloud concepts?","a":"<p><strong>Command groups</strong> (a menu of commands or more groups), <strong>commands</strong>, <strong>configurations</strong> (named sets of properties; the default one is called <code>default</code>), and <strong>properties</strong> (individual settings, in <code>section/property</code> form).</p>","hand":true},{"id":"gcp-f0024","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"What are the alpha and beta command groups in gcloud?","a":"<p>They hold commands still in development. They may change and give early access to features not yet generally released.</p>","hand":true},{"id":"gcp-f0025","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"Why use multiple gcloud configurations?","a":"<p>They let you switch projects without setting and unsetting each property.</p>","hand":true},{"id":"gcp-f0026","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"Which command verifies logged-in gcloud accounts, and how is the active one marked?","a":"<p><code>gcloud auth list</code>. The active account has an asterisk <code>*</code>.</p>","hand":true},{"id":"gcp-f0027","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"Which gcloud commands explore command groups and help, including an alpha variant?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud\ngcloud ai-platform\ngcloud ai-platform --help\ngcloud alpha ai-platform          # alpha variant of a group</code></pre></div>","hand":true},{"id":"gcp-f0028","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"Which gcloud commands list properties and configurations?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud config list                # current properties\ngcloud config list --all          # all possible options\ngcloud config configurations list # all named configurations</code></pre></div>","hand":true},{"id":"gcp-f0029","card":"q-gcp-008-gcloud-concepts","sec":"gcp-s008","q":"How do you set and unset a gcloud property?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud config set redis/region us-central1   # section/property value\ngcloud config unset &lt;section/property&gt;</code></pre></div>","hand":true},{"id":"gcp-f0030","card":"q-gcp-009-environments","sec":"gcp-s009","q":"What are the two App Engine environments?","a":"<p><strong>Standard</strong> and <strong>Flexible</strong>.</p>","hand":true},{"id":"gcp-f0031","card":"q-gcp-009-environments","sec":"gcp-s009","q":"What are the characteristics of the App Engine Standard environment?","a":"<p>It is opinionated and optimized for Google Cloud, deploys faster, and can scale to <strong>zero</strong> instances. It is less flexible and portable.</p>","hand":true},{"id":"gcp-f0032","card":"q-gcp-009-environments","sec":"gcp-s009","q":"What are the characteristics of the App Engine Flexible environment?","a":"<p>It is more flexible and portable, but slower to deploy.</p>","hand":true},{"id":"gcp-f0033","card":"q-gcp-009-environments","sec":"gcp-s009","q":"Which languages does App Engine support?","a":"<p>Go, PHP, Java, Python, Node.js and more.</p>","hand":true},{"id":"gcp-f0034","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"What is <code>app.yaml</code> in an App Engine app and which property is required?","a":"<p>It is the App Engine config. <code>runtime</code> is the only required property (e.g. <code>nodejs12</code>, <code>python37</code>, <code>go112</code>).</p>","hand":true},{"id":"gcp-f0035","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"What is the <code>app.yaml</code> for a minimal Node.js App Engine app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>runtime: nodejs10</code></pre></div>","hand":true},{"id":"gcp-f0036","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"Which script in <code>package.json</code> does App Engine run?","a":"<p>The <code>start</code> script.</p>","hand":true},{"id":"gcp-f0037","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"What must <code>app.js</code> listen on in App Engine?","a":"<p>The <code>PORT</code> environment variable that App Engine provides.</p>","hand":true},{"id":"gcp-f0038","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"What does a minimal Express <code>app.js</code> for App Engine look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const express = require(&#x27;express&#x27;);\nconst app = express();\n\napp.get(&#x27;/&#x27;, (req, res) =&gt; {\n  res\n    .status(200)\n    .send(&#x27;Hello, world!&#x27;)\n    .end();\n});\n\nconst PORT = process.env.PORT || 8080;\napp.listen(PORT, () =&gt; {\n  console.log(`App listening on port ${PORT}`);\n  console.log(&#x27;Press Ctrl+C to quit.&#x27;);\n});\n\nmodule.exports = app;</code></pre></div>","hand":true},{"id":"gcp-f0039","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"How do you run an App Engine Node.js app locally and deploy it?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm start\ngcloud app deploy app.yaml</code></pre></div>\n<p>Locally the app is at http://localhost:8080.</p>","hand":true},{"id":"gcp-f0040","card":"q-gcp-010-minimal-app-files","sec":"gcp-s010","q":"Which <code>package.json</code> script and dependency does the Hello World App Engine app use?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&quot;scripts&quot;: {\n    &quot;start&quot;: &quot;node app.js&quot;\n  },\n  &quot;dependencies&quot;: {\n    &quot;express&quot;: &quot;^4.16.3&quot;\n  }</code></pre></div>","hand":true},{"id":"gcp-f0041","card":"q-gcp-011-custom-domain","sec":"gcp-s011","q":"What is the default URL of an App Engine app and where do you set up a custom domain?","a":"<p>The default URL is a subdomain of <code>appspot.com</code>. Set up a custom domain under App Engine, Settings, Custom Domains: link an existing domain or register a new one.</p>","hand":true},{"id":"gcp-f0042","card":"q-gcp-011-custom-domain","sec":"gcp-s011","q":"How do you verify an existing domain for App Engine?","a":"<p>Pick the registrar, copy the <strong>TXT record</strong> into the domain's DNS, then click Verify. DNS propagation can take minutes, and the TXT value does not change, so retrying is safe.</p>","hand":true},{"id":"gcp-f0043","card":"q-gcp-011-custom-domain","sec":"gcp-s011","q":"What do you do after verifying a custom domain in App Engine?","a":"<p>Select the verified domain, map the domain and <code>www</code> subdomain, save, and add the DNS records Google lists.</p>","hand":true},{"id":"gcp-f0044","card":"q-gcp-011-custom-domain","sec":"gcp-s011","q":"How does HTTPS work for an App Engine custom domain by default?","a":"<p>Google provisions a <strong>managed, auto-renewing SSL certificate</strong> automatically (about 15 minutes), so HTTPS works with no extra setup.</p>","hand":true},{"id":"gcp-f0045","card":"q-gcp-012-bring-your-own-ssl-certificate","sec":"gcp-s012","q":"What are the steps to use your own SSL certificate on App Engine?","a":"<ol>\n  <li>Verify the domain, then disable managed security (Settings, Custom Domains, Disable managed security).</li>\n  <li>Convert the key to unencrypted PEM and concatenate the certificate chain into one file. <code>END CERTIFICATE</code> and <code>BEGIN CERTIFICATE</code> must be on separate lines.</li>\n  <li>Confirm that certificate and key match (both commands must print the same hash).</li>\n  <li>Upload under Settings, SSL Certificates (PEM public certificate + PEM private key), assign it to the domain, save.</li>\n</ol>","hand":true},{"id":"gcp-f0046","card":"q-gcp-012-bring-your-own-ssl-certificate","sec":"gcp-s012","q":"Which commands convert the private key to PEM and build the combined certificate chain file?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>openssl rsa -in &lt;your-private-key&gt;.key -out &lt;your-private-key&gt;.pem\ncat &lt;your-certificate&gt;.crt &lt;intermediate-ca&gt;.crt &lt;root-ca&gt;.crt &gt; &lt;combined-certificate&gt;.pem</code></pre></div>","hand":true},{"id":"gcp-f0047","card":"q-gcp-012-bring-your-own-ssl-certificate","sec":"gcp-s012","q":"How do you confirm that an SSL certificate and its private key match?","a":"<p>Run both commands. They must output the same string.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>openssl x509 -noout -modulus -in &lt;combined-certificate&gt;.pem | openssl md5\nopenssl rsa -noout -modulus -in &lt;your-private-key&gt;.pem | openssl md5</code></pre></div>","hand":true},{"id":"gcp-f0048","card":"q-gcp-013-hierarchy","sec":"gcp-s013","q":"How many App Engine applications can a Google Cloud project have?","a":"<p>Only <strong>one</strong>.</p>","hand":true},{"id":"gcp-f0049","card":"q-gcp-013-hierarchy","sec":"gcp-s013","q":"What is the App Engine hierarchy?","a":"<p>The App Engine application, then <strong>Services</strong> (multiple), then <strong>Versions</strong> (multiple per service), then <strong>Instances</strong> (multiple per version).</p>","hand":true},{"id":"gcp-f0050","card":"q-gcp-013-hierarchy","sec":"gcp-s013","q":"What are an App Engine Service, Version and Instance?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Component</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Service</strong></td><td>Acts like a microservice (user API, batch processing, admin panel)</td></tr>\n      <tr><td><strong>Version</strong></td><td>A deployment of a service (v1 main, v2 bug fixes, v3/v4 A/B tests)</td></tr>\n      <tr><td><strong>Instance</strong></td><td>Unit of capacity; scales up/down automatically or manually</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0051","card":"q-gcp-014-component-specific-urls","sec":"gcp-s014","q":"What is the App Engine URL of the default service?","a":"<p><code>&lt;project-id&gt;.&lt;region-id&gt;.r.appspot.com</code></p>","hand":true},{"id":"gcp-f0052","card":"q-gcp-014-component-specific-urls","sec":"gcp-s014","q":"What is the App Engine URL of a specific service?","a":"<p><code>&lt;service-id&gt;-dot-&lt;project-id&gt;.&lt;region-id&gt;.r.appspot.com</code></p>","hand":true},{"id":"gcp-f0053","card":"q-gcp-014-component-specific-urls","sec":"gcp-s014","q":"What is the App Engine URL of a specific version of a specific service?","a":"<p><code>&lt;version-id&gt;-dot-&lt;service-id&gt;-dot-&lt;project-id&gt;.&lt;region-id&gt;.r.appspot.com</code></p>","hand":true},{"id":"gcp-f0054","card":"q-gcp-014-component-specific-urls","sec":"gcp-s014","q":"What is the App Engine URL of a specific version of the default service?","a":"<p><code>&lt;version-id&gt;-dot-&lt;project-id&gt;.&lt;region-id&gt;.r.appspot.com</code></p>","hand":true},{"id":"gcp-f0055","card":"q-gcp-014-component-specific-urls","sec":"gcp-s014","q":"What do App Engine tools let you do with versions?","a":"<p>Roll versions out gradually, roll back, and serve multiple versions at once.</p>","hand":true},{"id":"gcp-f0056","card":"q-gcp-015-multi-environment-best-practice","sec":"gcp-s015","q":"Why use separate projects for test and production in App Engine instead of separate services?","a":"<p>Services in one project share data (Firestore, Cloud Storage), which risks cross-contamination.</p>","hand":true},{"id":"gcp-f0057","card":"q-gcp-015-multi-environment-best-practice","sec":"gcp-s015","q":"What is the recommended App Engine version naming scheme and why?","a":"<p><code>&lt;timestamp&gt;-&lt;git-commit-hash&gt;</code>. The timestamp gives deployment order. The hash identifies the exact commit, which makes rollback precise.</p>","hand":true},{"id":"gcp-f0058","card":"q-gcp-015-multi-environment-best-practice","sec":"gcp-s015","q":"How should the App Engine test project be organized?","a":"<p>The default version is the latest production version. Each feature branch is its own version (<code>feature-x</code>, <code>feature-y</code>), so QA can test them in parallel via unique version URLs.</p>","hand":true},{"id":"gcp-f0059","card":"q-gcp-015-multi-environment-best-practice","sec":"gcp-s015","q":"How should the App Engine production project be organized?","a":"<p>Versions are named by timestamp + commit and are used for migrations and rollbacks. Feature versions can be tried on real users via traffic splitting.</p>","hand":true},{"id":"gcp-f0060","card":"q-gcp-015-multi-environment-best-practice","sec":"gcp-s015","q":"What is the natural next step after a multi-environment App Engine setup?","a":"<p>Automate it with CI/CD.</p>","hand":true},{"id":"gcp-f0061","card":"q-gcp-016-traffic-splitting-and-rollback","sec":"gcp-s016","q":"How do you split traffic between App Engine versions in the console?","a":"<p>App Engine, Versions, <strong>Split Traffic</strong>, choose a method, add versions with percentages, Save.</p>","hand":true},{"id":"gcp-f0062","card":"q-gcp-016-traffic-splitting-and-rollback","sec":"gcp-s016","q":"What are the three App Engine traffic splitting methods and when is each best?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Method</th><th>How it routes</th><th>Best for</th></tr></thead>\n    <tbody>\n      <tr><td><strong>IP address</strong></td><td>By request IP</td><td>Non-browser clients, apps without cookies</td></tr>\n      <tr><td><strong>Cookie</strong></td><td>By cookie value</td><td>Browser apps (you must add the cookie)</td></tr>\n      <tr><td><strong>Random</strong></td><td>By percentage</td><td>Quick tests (one user may hit different versions across requests)</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0063","card":"q-gcp-016-traffic-splitting-and-rollback","sec":"gcp-s016","q":"What does Migrate Traffic do in App Engine?","a":"<p>You select a version, confirm, and 100% of traffic goes to it.</p>","hand":true},{"id":"gcp-f0064","card":"q-gcp-016-traffic-splitting-and-rollback","sec":"gcp-s016","q":"How do you roll back an App Engine deployment?","a":"<p>Migrate all traffic back to an earlier version. Rollback is the same operation as Migrate Traffic.</p>","hand":true},{"id":"gcp-f0065","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"What is Cloud SQL?","a":"<p>Fully managed MySQL, Postgres and SQL Server. Google handles uptime, replication, backups and scaling.</p>","hand":true},{"id":"gcp-f0066","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"Which fields does the Cloud SQL create instance form ask for?","a":"<p>Instance ID, root password (manual, auto-created, or none), region and zone, and database version.</p>","hand":true},{"id":"gcp-f0067","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"Which Cloud SQL location choice is permanent?","a":"<p>The region is permanent. The zone can be changed. Keep the DB in the same location as the services using it.</p>","hand":true},{"id":"gcp-f0068","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"Private IP vs Public IP for Cloud SQL?","a":"<p><strong>Private IP</strong> is reachable only inside or through your VPC. <strong>Public IP</strong> is reachable from anywhere, and you connect via <strong>Cloud SQL Proxy</strong> or allowlisted IPs.</p>","hand":true},{"id":"gcp-f0069","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"What machine types and storage options does Cloud SQL offer?","a":"<p>Machine type ranges from 1 vCPU / ~1 GB up to 96 vCPUs / 600+ GB RAM, and network throughput grows with size. Storage is SSD (fast) or HDD. Enable automatic storage increases. Disk throughput grows with capacity.</p>","hand":true},{"id":"gcp-f0070","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"What are automatic backups and point-in-time recovery in Cloud SQL?","a":"<p>Automatic backups are scheduled backups. Point-in-time recovery restores to a specific moment.</p>","hand":true},{"id":"gcp-f0071","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"What is Cloud SQL high availability?","a":"<p>A replica in another zone with automatic failover. It is recommended for production.</p>","hand":true},{"id":"gcp-f0072","card":"q-gcp-017-cloud-sql","sec":"gcp-s017","q":"What are Cloud SQL flags, maintenance window and labels?","a":"<p>Flags are DB flags. The maintenance window is the preferred maintenance time. Labels organize instances (e.g. <code>environment: production</code>).</p>","hand":true},{"id":"gcp-f0073","card":"q-gcp-018-service-accounts-iam","sec":"gcp-s018","q":"What is a GCP service account?","a":"<p>A user-like identity for applications. There are two kinds, user-created and Google-managed, with no functional difference.</p>","hand":true},{"id":"gcp-f0074","card":"q-gcp-018-service-accounts-iam","sec":"gcp-s018","q":"What is the App Engine default service account and how do you let the app use Cloud SQL?","a":"<p>It is <code>&lt;project-id&gt;@appspot.gserviceaccount.com</code>. Add a role to it via IAM &amp; Admin, IAM, Edit, Add Another Role (e.g. <code>Cloud SQL Client</code>; <code>Cloud SQL Editor</code> or <code>Admin</code> also work).</p>","hand":true},{"id":"gcp-f0075","card":"q-gcp-018-service-accounts-iam","sec":"gcp-s018","q":"How do you create a new service account and a key for it?","a":"<p>Under Service Accounts, enter name, ID and description, then roles, and optionally grant users access. For a key: Add Key, Create New Key, JSON.</p>","hand":true},{"id":"gcp-f0076","card":"q-gcp-018-service-accounts-iam","sec":"gcp-s018","q":"Why must a service account JSON key be treated as a secret?","a":"<p>The file downloads only once.</p>","hand":true},{"id":"gcp-f0077","card":"q-gcp-018-service-accounts-iam","sec":"gcp-s018","q":"Disabling vs deleting a service account?","a":"<p><strong>Disable</strong> is temporary and reversible. <strong>Delete</strong> is permanent.</p>","hand":true},{"id":"gcp-f0078","card":"q-gcp-019-connecting-from-app-engine-unix-socket","sec":"gcp-s019","q":"What does an App Engine app need to connect to Cloud SQL over a Unix socket?","a":"<p>The instance's <strong>Public IP</strong>, its <strong>INSTANCE_CONNECTION_NAME</strong> (<code>project-id:region:instance-name</code>), and the service account role (such as Cloud SQL Client).</p>","hand":true},{"id":"gcp-f0079","card":"q-gcp-019-connecting-from-app-engine-unix-socket","sec":"gcp-s019","q":"How does a deployed App Engine app connect to Cloud SQL?","a":"<p>It authenticates with the App Engine service account and connects over a Unix socket at <code>/cloudsql/&lt;connection_name&gt;</code>.</p>","hand":true},{"id":"gcp-f0080","card":"q-gcp-019-connecting-from-app-engine-unix-socket","sec":"gcp-s019","q":"Where do <code>env_variables</code> in <code>app.yaml</code> take effect?","a":"<p>Only when the app is <strong>deployed</strong>, not locally.</p>","hand":true},{"id":"gcp-f0081","card":"q-gcp-019-connecting-from-app-engine-unix-socket","sec":"gcp-s019","q":"What does <code>app.yaml</code> look like for an App Engine app connecting to Cloud SQL?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>runtime: nodejs10\nenv_variables:\n  CLOUD_SQL_CONNECTION_NAME: &quot;&lt;project-id&gt;:&lt;region&gt;:&lt;instance-name&gt;&quot;\n  DB_USER: &quot;&lt;db_user&gt;&quot;\n  DB_PASS: &quot;&lt;db_password&gt;&quot;\n  DB_NAME: &quot;&lt;db_name&gt;&quot;</code></pre></div>","hand":true},{"id":"gcp-f0082","card":"q-gcp-019-connecting-from-app-engine-unix-socket","sec":"gcp-s019","q":"Which command deploys an App Engine app with its <code>app.yaml</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud app deploy app.yaml</code></pre></div>","hand":true},{"id":"gcp-f0083","card":"q-gcp-020-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"Why do you need Cloud SQL Proxy for local development?","a":"<p>Locally, the App Engine service account does not apply. The <strong>Cloud SQL Proxy</strong> authenticates with a valid account and exposes the DB on <code>localhost:3306</code>.</p>","hand":true},{"id":"gcp-f0084","card":"q-gcp-020-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"What are the prerequisites for Cloud SQL Proxy?","a":"<p>A Cloud SQL instance, an account with permissions above <code>Cloud SQL Viewer</code>, a MySQL client, <strong>Cloud SQL Admin API enabled</strong>, and the right account active in gcloud (<code>gcloud auth list</code>).</p>","hand":true},{"id":"gcp-f0085","card":"q-gcp-020-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"What database practice is recommended for production and development with Cloud SQL?","a":"<p>Use different databases for production and development.</p>","hand":true},{"id":"gcp-f0086","card":"q-gcp-020-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"Which commands download and start the Cloud SQL Proxy?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>curl -o cloud-sql-proxy https://storage.googleapis.com/cloud-sql-connectors/cloud-sql-proxy/v2.0.0/cloud-sql-proxy.darwin.amd64\nchmod +x cloud-sql-proxy\n\n./cloud-sql-proxy &lt;project-id&gt;:&lt;region&gt;:&lt;instance-name&gt; --port 3306</code></pre></div>\n<p>The proxy listens on localhost:3306.</p>","hand":true},{"id":"gcp-f0087","card":"q-gcp-020-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"What does the local <code>.env</code> file look like for the Cloud SQL Proxy setup?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>CLOUD_SQL_CONNECTION_NAME=&quot;&lt;project-id&gt;:&lt;region&gt;:&lt;instance-name&gt;&quot;\nDB_USER=&quot;&lt;db_user&gt;&quot;\nDB_PASS=&quot;&lt;db_password&gt;&quot;\nDB_NAME=&quot;&lt;db_name&gt;&quot;\nDB_HOST=&quot;localhost:3306&quot;</code></pre></div>\n<p>It is for local use only. Do not deploy it.</p>","hand":true},{"id":"gcp-f0088","card":"q-gcp-021-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"How does the final Node.js app choose between TCP and Unix socket for Cloud SQL?","a":"<p>When <code>DB_HOST</code> is set (local, via proxy) it uses TCP, otherwise the Unix socket (deployed).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const createPool = async (config) =&gt; {\n  if (process.env.DB_HOST) {\n    return await createTcpPool(config);\n  } else {\n    return await createUnixSocketPool(config);\n  }\n}</code></pre></div>","hand":true},{"id":"gcp-f0089","card":"q-gcp-021-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"How does a Node.js app build a Cloud SQL Unix socket pool with mysql?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const createUnixSocketPool = async (config) =&gt; {\n  const dbSocketPath = process.env.DB_SOCKET_PATH || &quot;/cloudsql&quot;\n  return await mysql.createPool({\n    user: process.env.DB_USER,\n    password: process.env.DB_PASS,\n    database: process.env.DB_NAME,\n    socketPath: `${dbSocketPath}/${process.env.CLOUD_SQL_CONNECTION_NAME}`,\n    ...config\n  });\n}</code></pre></div>","hand":true},{"id":"gcp-f0090","card":"q-gcp-021-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"How does a Node.js app build a TCP pool to Cloud SQL through the proxy?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const createTcpPool = async (config) =&gt; {\n  const dbSocketAddr = process.env.DB_HOST.split(&quot;:&quot;)\n  return await mysql.createPool({\n    user: process.env.DB_USER,\n    password: process.env.DB_PASS,\n    database: process.env.DB_NAME,\n    host: dbSocketAddr[0],\n    port: dbSocketAddr[1],\n    ...config\n  });\n}</code></pre></div>","hand":true},{"id":"gcp-f0091","card":"q-gcp-021-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"How does the Cloud SQL test route check the connection?","a":"<p>It runs <code>SELECT 1 + 1 AS solution</code>. On error it returns status 500 with \"Error in connecting to database.\" On success it returns 200 with \"Connection to database successful!\".</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pool.query(&#x27;SELECT 1 + 1 AS solution&#x27;, function (error, results, fields) {</code></pre></div>","hand":true},{"id":"gcp-f0092","card":"q-gcp-021-cloud-sql-proxy-local-development","sec":"gcp-s020","q":"Unix socket vs TCP via Cloud SQL Proxy: when is each used and what is the connection?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Method</th><th>When</th><th>Connection</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Unix socket</strong></td><td>Deployed on App Engine</td><td><code>/cloudsql/&lt;connection_name&gt;</code></td></tr>\n      <tr><td><strong>TCP via Cloud SQL Proxy</strong></td><td>Local development</td><td><code>localhost:3306</code></td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0093","card":"q-gcp-022-6-cloud-storage-gcs","sec":"gcp-s021","q":"What are buckets and objects in Cloud Storage?","a":"<p>Data lives in <strong>buckets</strong> (virtually unlimited size). Files are <strong>objects</strong>.</p>","hand":true},{"id":"gcp-f0094","card":"q-gcp-022-6-cloud-storage-gcs","sec":"gcp-s021","q":"Why must Cloud Storage bucket names be globally unique?","a":"<p>Because they are part of the object URL.</p>","hand":true},{"id":"gcp-f0095","card":"q-gcp-023-location-types","sec":"gcp-s022","q":"What are the Cloud Storage location types?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Location</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Region</strong></td><td>Cheapest, single region</td></tr>\n      <tr><td><strong>Dual-region</strong></td><td>Most expensive, high availability/low latency across two regions</td></tr>\n      <tr><td><strong>Multi-region</strong></td><td>Highest availability across a large area (Americas, Europe, Asia Pacific); pick the one closest to users</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0096","card":"q-gcp-023-location-types","sec":"gcp-s022","q":"Which Cloud Storage location type is cheapest and which is most expensive?","a":"<p>Region is the cheapest (a single region). Dual-region is the most expensive.</p>","hand":true},{"id":"gcp-f0097","card":"q-gcp-024-storage-classes","sec":"gcp-s023","q":"What are the Cloud Storage storage classes and their cost trade-offs?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Class</th><th>Best for</th><th>Storage cost</th><th>Retrieval cost</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Standard</strong></td><td>Short-term, frequently accessed</td><td>Highest</td><td>Lowest</td></tr>\n      <tr><td><strong>Nearline</strong>, <strong>Coldline</strong></td><td>Middle ground</td><td>decreasing</td><td>increasing</td></tr>\n      <tr><td><strong>Archive</strong></td><td>Long-term, rarely accessed</td><td>Lowest</td><td>Highest</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0098","card":"q-gcp-024-storage-classes","sec":"gcp-s023","q":"What are Class A and Class B operations in Cloud Storage?","a":"<p><strong>Class A</strong> = writes (create bucket, upload, set permissions, delete). <strong>Class B</strong> = reads (download, view metadata/permissions).</p>","hand":true},{"id":"gcp-f0099","card":"q-gcp-024-storage-classes","sec":"gcp-s023","q":"What other options can you set on a Cloud Storage bucket?","a":"<p>Encryption (Google-managed or customer-managed key), a <strong>retention policy</strong>, and labels.</p>","hand":true},{"id":"gcp-f0100","card":"q-gcp-024-storage-classes","sec":"gcp-s023","q":"What does a Cloud Storage retention policy do?","a":"<p>It prevents deletion for a set period, e.g. for compliance.</p>","hand":true},{"id":"gcp-f0101","card":"q-gcp-025-upload-download-methods","sec":"gcp-s024","q":"How can you upload or download objects in Cloud Storage?","a":"<p>The Console (Upload Files/Folder), <code>gsutil cp</code>, client libraries, and the JSON/XML REST APIs.</p>","hand":true},{"id":"gcp-f0102","card":"q-gcp-025-upload-download-methods","sec":"gcp-s024","q":"Which gsutil commands upload a file to a bucket and download an object?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gsutil cp sunflower2.jpg gs://&lt;bucket-name&gt;/\ngsutil cp gs://&lt;bucket-name&gt;/sunflower2.jpg downloaded-sunflower.jpg</code></pre></div>","hand":true},{"id":"gcp-f0103","card":"q-gcp-026-access-control-uniform-vs-fine-grained","sec":"gcp-s025","q":"Uniform vs Fine-grained access control in Cloud Storage?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Mode</th><th>Description</th><th>Notes</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Uniform</strong></td><td>Bucket-level permissions, all objects inherit</td><td>Recommended, tends to cost less</td></tr>\n      <tr><td><strong>Fine-grained</strong></td><td>Per-object permissions (ACLs), one object public while another is private</td><td>Riskier, needs extra attention</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0104","card":"q-gcp-026-access-control-uniform-vs-fine-grained","sec":"gcp-s025","q":"Where do you switch a bucket between Uniform and Fine-grained access, and what is the warning?","a":"<p>Under the bucket's Permissions tab. Switching back to fine-grained restores previously set object ACLs, which may grant wider access than the bucket IAM policy.</p>","hand":true},{"id":"gcp-f0105","card":"q-gcp-026-access-control-uniform-vs-fine-grained","sec":"gcp-s025","q":"How do you make all objects in a Uniform bucket public, and how do you make them private again?","a":"<p>Add <code>allUsers</code> with role <code>Storage Object Viewer</code>, then Allow public access. Remove that permission to make them private again.</p>","hand":true},{"id":"gcp-f0106","card":"q-gcp-026-access-control-uniform-vs-fine-grained","sec":"gcp-s025","q":"What happens to per-object \"Edit permissions\" under Uniform access?","a":"<p>It disappears.</p>","hand":true},{"id":"gcp-f0107","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"What is a Cloud Storage signed URL?","a":"<p>It gives <strong>temporary access to a private object</strong>.</p>","hand":true},{"id":"gcp-f0108","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"What is the signed URL flow?","a":"<p>The user asks the app, the app signs a URL using a service account, and the user fetches the object directly from GCS.</p>","hand":true},{"id":"gcp-f0109","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"What parts does a V4 signed URL have?","a":"<p>Object path, signing algorithm, credentials, start date (can be in the future), expiry (seconds from start, up to <strong>7 days</strong>), signed headers, and signature.</p>","hand":true},{"id":"gcp-f0110","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"What is the maximum expiry of a V4 signed URL?","a":"<p>Up to <strong>7 days</strong> (seconds from the start date).</p>","hand":true},{"id":"gcp-f0111","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"What does generating a signed URL need?","a":"<p>A service account with at least <strong>Storage Object Viewer</strong> (<code>storage.objects.get</code>) and its downloaded private key.</p>","hand":true},{"id":"gcp-f0112","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"Which key does a signed URL use locally and on GCP?","a":"<p>Locally you must pass the key file. On GCP the default service account is used automatically.</p>","hand":true},{"id":"gcp-f0113","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"How do you make a signed upload URL?","a":"<p>Use the same code with <code>action: 'write'</code>.</p>","hand":true},{"id":"gcp-f0114","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"Which command creates a signed URL valid for 10 minutes with gsutil?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gsutil signurl -d 10m &lt;service-account-key&gt;.json gs://&lt;bucket-name&gt;/&lt;file-name&gt;</code></pre></div>","hand":true},{"id":"gcp-f0115","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"How do you create a V4 read signed URL valid for 15 minutes in Node.js?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const {Storage} = require(&#x27;@google-cloud/storage&#x27;);\nconst storage = new Storage({\n  keyFilename: &#x27;&lt;service-account-key&gt;.json&#x27;\n});\n\nasync function generateV4ReadSignedUrl() {\n  const options = {\n    version: &#x27;v4&#x27;,\n    action: &#x27;read&#x27;,\n    expires: Date.now() + 15 * 60 * 1000, // 15 minutes\n  };\n\n  const [url] = await storage\n    .bucket(bucketName)\n    .file(filename)\n    .getSignedUrl(options);\n}</code></pre></div>","hand":true},{"id":"gcp-f0116","card":"q-gcp-027-signed-urls","sec":"gcp-s026","q":"Which commands install the Cloud Storage client library and run the signed URL script?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm install @google-cloud/storage\nnode signurl.js</code></pre></div>","hand":true},{"id":"gcp-f0117","card":"q-gcp-028-object-lifecycle-management","sec":"gcp-s027","q":"What are Cloud Storage lifecycle rules and where are they set?","a":"<p>Rules apply to <strong>all objects</strong> in a bucket. Age counts from when the object was added. Set them under bucket, Lifecycle tab, Add a Rule (action, then conditions).</p>","hand":true},{"id":"gcp-f0118","card":"q-gcp-028-object-lifecycle-management","sec":"gcp-s027","q":"Which lifecycle rule wins when an object matches several rules?","a":"<p>The <strong>least-costly-to-keep action wins</strong>: Delete beats downgrade to the lowest class, which beats downgrade to a higher class.</p>","hand":true},{"id":"gcp-f0119","card":"q-gcp-028-object-lifecycle-management","sec":"gcp-s027","q":"Which actions and conditions can a Cloud Storage lifecycle rule use?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Actions</th><th>Conditions</th></tr></thead>\n    <tbody>\n      <tr><td>Set storage class (e.g. Standard to Archive), Delete</td><td>Age (days since upload), creation date, storage class, newer versions + live state (versioning)</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0120","card":"q-gcp-028-object-lifecycle-management","sec":"gcp-s027","q":"What lifecycle rules suit a file download service?","a":"<p>Rule 1 sets class to <strong>Archive</strong> at age 30 days and class Standard. Rule 2 <strong>deletes</strong> at age 365 days, so links expire after a year.</p>","hand":true},{"id":"gcp-f0121","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"What is Cloud Tasks and what are its two target types?","a":"<p>It creates tasks and runs them in the background. The targets are <strong>App Engine tasks</strong> (endpoints in an App Engine app) and <strong>HTTP target tasks</strong> (any public URL).</p>","hand":true},{"id":"gcp-f0122","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"What does a Cloud Tasks task contain?","a":"<p>A name (set automatically when you give none), target POST URL, payload, optional schedule time (otherwise ASAP) and a queue.</p>","hand":true},{"id":"gcp-f0123","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"What are the Cloud Tasks queue settings for rate?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Queue setting</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td>Rate of execution / max dispatches per second</td><td>Tasks per second</td></tr>\n      <tr><td>Max concurrent dispatches</td><td>Cap on parallel executions, protects endpoints</td></tr>\n      <tr><td>Max burst size</td><td>Burstable rates via token buckets</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0124","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"What are the Cloud Tasks retry settings and example values?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Retry setting</th><th>Example</th><th>Meaning</th></tr></thead>\n    <tbody>\n      <tr><td>Max attempts</td><td>100</td><td>Max retries</td></tr>\n      <tr><td>Min backoff</td><td>100 ms</td><td>Wait before first retry</td></tr>\n      <tr><td>Backoff doubling</td><td>up to 16 times</td><td>Wait doubles on each failure</td></tr>\n      <tr><td>Max backoff</td><td>3,600 s</td><td>Longest wait between retries</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0125","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"What controls does the console offer for a Cloud Tasks queue?","a":"<p><strong>Pause</strong>/<strong>Resume</strong> a queue, <strong>Run now</strong> for one task, <strong>Delete</strong> a task, and <strong>Purge</strong> all tasks.</p>","hand":true},{"id":"gcp-f0126","card":"q-gcp-029-concepts","sec":"gcp-s028","q":"Which gcloud commands create and describe a Cloud Tasks queue?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud tasks queues create test-queue\ngcloud tasks queues describe test-queue</code></pre></div>","hand":true},{"id":"gcp-f0127","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"What are the key points of creating a Cloud Task from App Engine?","a":"<p>Use <code>appEngineHttpRequest</code> with POST and a relative URI, a payload base64-encoded in <code>body</code>, and an optional <code>scheduleTime</code>.</p>","hand":true},{"id":"gcp-f0128","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"Why does the Cloud Tasks example use a body-parser setup with <code>rawBodySaver</code>?","a":"<p>It keeps the raw body so task payloads can be read in the handler.</p>","hand":true},{"id":"gcp-f0129","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"How do you build the Cloud Tasks queue path and the task object in Node.js?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const client = new CloudTasksClient();\nconst parent = client.queuePath(project, location, queue);\n\nconst task = {\n  appEngineHttpRequest: {\n    httpMethod: &#x27;POST&#x27;,\n    relativeUri: path,\n  },\n};</code></pre></div>","hand":true},{"id":"gcp-f0130","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"How do you add a base64 payload and a delay to a Cloud Task in Node.js?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if (payload) {\n  task.appEngineHttpRequest.body = Buffer.from(JSON.stringify(payload)).toString(&#x27;base64&#x27;);\n}\n\nif (inSeconds) {\n  task.scheduleTime = {\n    seconds: inSeconds + Date.now() / 1000,\n  };\n}</code></pre></div>","hand":true},{"id":"gcp-f0131","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"How do you send the task to Cloud Tasks with the Node.js client?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const request = {parent, task};\nconst [response] = await client.createTask(request);\nconsole.log(`Created task ${response.name}`);</code></pre></div>","hand":true},{"id":"gcp-f0132","card":"q-gcp-030-creating-a-task-from-app-engine-exercise","sec":"gcp-s029","q":"Which routes trigger and handle the Cloud Task in the exercise?","a":"<p><code>/create_task</code> creates the task on <code>test-queue</code> with a relative path <code>/task_endpoint</code>. <code>/task_endpoint</code> handles the POST and returns \"Task processed\".</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>await createTask(&#x27;test-queue&#x27;, { payload: &#x27;hello&#x27; }, &#x27;/task_endpoint&#x27;);</code></pre></div>","hand":true},{"id":"gcp-f0133","card":"q-gcp-031-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What setup does the email fan-out exercise need?","a":"<p>Enable the <strong>Cloud Tasks API</strong>, then create two queues.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud tasks queues create email-task-generator\ngcloud tasks queues create email-sender</code></pre></div>","hand":true},{"id":"gcp-f0134","card":"q-gcp-031-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What is the problem with sending emails in a loop?","a":"<p>It is fine for few recipients, but with thousands or hundreds of thousands the loop times out.</p>","hand":true},{"id":"gcp-f0135","card":"q-gcp-031-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"Direct vs Task per email vs Fan-out for sending emails?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Pattern</th><th>Description</th><th>Scalability</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Direct</strong></td><td>Loop and send synchronously</td><td>Does not scale, risks timeout</td></tr>\n      <tr><td><strong>Task per email</strong></td><td>One Cloud Task per email</td><td>Better, but the task-creation loop can still time out</td></tr>\n      <tr><td><strong>Fan-out</strong></td><td>Generator tasks each create the send tasks for a batch</td><td>Best; parallel, App Engine auto-scales instances</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0136","card":"q-gcp-031-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What is the fan-out pattern with Cloud Tasks?","a":"<p>Create <em>tasks that create tasks</em>. Example: 100,000 emails with batch size 100 gives 1,000 generator tasks. Each receives <code>startCount</code> and <code>batchSize</code>, queries that slice from the DB, and creates the individual send-email tasks.</p>","hand":true},{"id":"gcp-f0137","card":"q-gcp-031-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What does the sample <code>emailService.js</code> do?","a":"<p>It exports <code>sendEmail</code>, which only logs that an email was sent.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const sendEmail = (email, subject, emailBody) =&gt; {\n  console.log(`Email sent to ${email}`);\n};\nexports.sendEmail = sendEmail;</code></pre></div>","hand":true},{"id":"gcp-f0138","card":"q-gcp-032-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"How does <code>dbService.js</code> return a batch of email addresses?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const getEmailReceivers = async (startCount=0, limit=1000) =&gt; {\n  const pool = await createPool({});\n  const sql = &quot;SELECT email from emails LIMIT ?, ?&quot;;\n  const [results] = await pool.query(sql, [startCount, limit]);\n  return results.map(result =&gt; result.email);\n};</code></pre></div>","hand":true},{"id":"gcp-f0139","card":"q-gcp-032-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What does <code>getTotalNumberOfEmails</code> return in the fan-out exercise?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const getTotalNumberOfEmails = async () =&gt; {\n  return 100000;\n};</code></pre></div>","hand":true},{"id":"gcp-f0140","card":"q-gcp-032-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"In <code>dbService.js</code>, how does <code>createPool</code> return a promise-based pool?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const createPool = async (config) =&gt; {\n  let pool;\n  if (process.env.DB_HOST) {\n    pool = await createTcpPool(config);\n  } else {\n    pool = await createUnixSocketPool(config);\n  }\n  return pool.promise();\n}</code></pre></div>","hand":true},{"id":"gcp-f0141","card":"q-gcp-032-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"Which MySQL package does the fan-out <code>dbService.js</code> use?","a":"<p><code>mysql2</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const mysql = require(&#x27;mysql2&#x27;);</code></pre></div>","hand":true},{"id":"gcp-f0142","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What are the queue names and email constants in the fan-out <code>app.js</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const generatorTaskQueueName = &#x27;email-task-generator&#x27;;\nconst senderTaskQueueName = &#x27;email-sender&#x27;;\nconst subject = `You&#x27;ve got mail!`;\nconst emailBody = &#x27;Hello!&#x27;;</code></pre></div>","hand":true},{"id":"gcp-f0143","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What does the <code>/send-emails-normally</code> route do?","a":"<p>It sends emails directly in a loop (the Direct pattern).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const emails = await dbService.getEmailReceivers();\nemails.forEach(email =&gt; {\n  emailService.sendEmail(email, subject, emailBody);\n});</code></pre></div>","hand":true},{"id":"gcp-f0144","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"How does the <code>/create-send-email-tasks</code> route send emails?","a":"<p>It creates one Cloud Task per email on the sender queue.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for (var i = 0; i &lt; emails.length; i++) {\n  await createTask(senderTaskQueueName, { email: emails[i], subject, emailBody }, &#x27;/send-email&#x27;);\n}</code></pre></div>","hand":true},{"id":"gcp-f0145","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"How does the <code>/send-emails-fan-out</code> route create generator tasks?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const totalEmails = await dbService.getTotalNumberOfEmails();\nconst batchSize = 100;\nlet startCount = 0;\nconst numberOfBatches = Math.round(totalEmails / batchSize);\nfor (let i = 0; i &lt; numberOfBatches; i++) {\n  await createTask(generatorTaskQueueName, { startCount, batchSize }, &#x27;/generate-send-email-tasks&#x27;);\n  startCount += batchSize;\n}</code></pre></div>","hand":true},{"id":"gcp-f0146","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What does the <code>/generate-send-email-tasks</code> handler do?","a":"<p>It reads <code>startCount</code> and <code>batchSize</code> from the request body, loads that slice of emails and creates one send task per email.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const emails = await dbService.getEmailReceivers(req.body.startCount, req.body.batchSize);</code></pre></div>","hand":true},{"id":"gcp-f0147","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What does the <code>/send-email</code> handler do?","a":"<p>It calls <code>emailService.sendEmail</code> with the email, subject and body from the request body.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>emailService.sendEmail(req.body.email, req.body.subject, req.body.emailBody);</code></pre></div>","hand":true},{"id":"gcp-f0148","card":"q-gcp-033-emailing-subscribers-fan-out-pattern-exe","sec":"gcp-s030","q":"What extra <code>app.yaml</code> line does the fan-out demo add?","a":"<p><code>instance_class: F1</code> under <code>runtime</code>, as the instance class for the demo. The rest is the same as the Cloud SQL <code>app.yaml</code>.</p>","hand":true},{"id":"gcp-f0149","card":"q-gcp-034-8-cloud-scheduler-cron","sec":"gcp-s031","q":"What is Cloud Scheduler?","a":"<p>A fully managed cron service. It triggers <strong>HTTPS endpoints</strong> or <strong>Pub/Sub topics</strong> on a schedule.</p>","hand":true},{"id":"gcp-f0150","card":"q-gcp-034-8-cloud-scheduler-cron","sec":"gcp-s031","q":"What are example use cases for Cloud Scheduler?","a":"<p>Daily summary emails at 7am, deactivating users inactive for a month at midnight, and a weekly Sunday-midnight backup script.</p>","hand":true},{"id":"gcp-f0151","card":"q-gcp-034-8-cloud-scheduler-cron","sec":"gcp-s031","q":"Which fields does a Cloud Scheduler job have?","a":"<p>Name (unique in project), description, frequency (<strong>Unix cron</strong>), timezone, and target.</p>","hand":true},{"id":"gcp-f0152","card":"q-gcp-035-cron-format","sec":"gcp-s032","q":"What are the five fields of a Unix cron schedule?","a":"<p>Space separated: minute (0-59), hour (0-23), day of month (1-31), month (1-12), day of week (0-6, Sun=0).</p>","hand":true},{"id":"gcp-f0153","card":"q-gcp-035-cron-format","sec":"gcp-s032","q":"What do the cron expressions <code>0 8 * * *</code>, <code>0 * * * *</code> and <code>0 0 * * 0</code> mean?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Example</th><th>Schedule</th></tr></thead>\n    <tbody>\n      <tr><td><code>0 8 * * *</code></td><td>Daily 8:00 AM</td></tr>\n      <tr><td><code>0 * * * *</code></td><td>Every hour on the hour</td></tr>\n      <tr><td><code>0 0 * * 0</code></td><td>Every Sunday midnight</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0154","card":"q-gcp-036-targets","sec":"gcp-s033","q":"What are the Cloud Scheduler target types?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Target</th><th>Notes</th></tr></thead>\n    <tbody>\n      <tr><td><strong>HTTP</strong></td><td>Any public URL (also use this for an App Engine app in <em>another</em> project)</td></tr>\n      <tr><td><strong>Pub/Sub</strong></td><td>Topic + payload</td></tr>\n      <tr><td><strong>App Engine HTTP</strong></td><td>App in the current project: relative path, service, method, version, instance</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0155","card":"q-gcp-036-targets","sec":"gcp-s033","q":"Which Cloud Scheduler target do you use for an App Engine app in another project?","a":"<p>The <strong>HTTP</strong> target.</p>","hand":true},{"id":"gcp-f0156","card":"q-gcp-037-timezone-caveats","sec":"gcp-s034","q":"What time does Cloud Scheduler use, and what goes wrong with daylight saving time?","a":"<p>It uses the <strong>wall-clock time</strong> of the chosen timezone. With daylight saving time, a job can run <strong>twice</strong> at the switch back or be <strong>skipped</strong> at the switch forward.</p>","hand":true},{"id":"gcp-f0157","card":"q-gcp-037-timezone-caveats","sec":"gcp-s034","q":"What is the best practice for Cloud Scheduler timezones?","a":"<p>Use UTC.</p>","hand":true},{"id":"gcp-f0158","card":"q-gcp-037-timezone-caveats","sec":"gcp-s034","q":"How do you email users at 8 AM in their own timezone with Cloud Scheduler?","a":"<p>Run the job <strong>every hour</strong> and filter by timezone in the endpoint code.</p>","hand":true},{"id":"gcp-f0159","card":"q-gcp-038-exercise-07-02-daily-subscriber-emails","sec":"gcp-s035","q":"What is the flow of the daily subscriber email exercise?","a":"<p>Scheduler fires every hour and POSTs <code>/generate-morning-email-tasks</code>. The DB is filtered for users whose timezone is at 8 AM. One Cloud Task is created per user, and each task POSTs <code>/send-email</code>.</p>","hand":true},{"id":"gcp-f0160","card":"q-gcp-038-exercise-07-02-daily-subscriber-emails","sec":"gcp-s035","q":"Which Cloud Scheduler job settings does the daily email exercise use?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Job setting</th><th>Value</th></tr></thead>\n    <tbody>\n      <tr><td>Name</td><td><code>send-daily-emails</code></td></tr>\n      <tr><td>Frequency</td><td><code>0 * * * *</code></td></tr>\n      <tr><td>Timezone</td><td>UTC</td></tr>\n      <tr><td>Target</td><td>App Engine HTTP, URL <code>/generate-morning-email-tasks</code>, method POST</td></tr>\n      <tr><td>Service/version/instance, body</td><td>Blank (defaults, endpoint needs no input)</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0161","card":"q-gcp-038-exercise-07-02-daily-subscriber-emails","sec":"gcp-s035","q":"How do you test a Cloud Scheduler job?","a":"<p>Run it manually from the console. The result should show Success.</p>","hand":true},{"id":"gcp-f0162","card":"q-gcp-038-exercise-07-02-daily-subscriber-emails","sec":"gcp-s035","q":"How does <code>dbService.js</code> filter users for the morning email?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const getFilteredUsersForMorningEmail = async () =&gt; {\n  const pool = await createPool({});\n  const timezone = &#x27;Pacific Daylight Time&#x27;;\n  const sql = &quot;SELECT email from emails WHERE timezone = ?&quot;;\n  const [results] = await pool.query(sql, [timezone]);\n  return results.map(result =&gt; result.email);\n};</code></pre></div>","hand":true},{"id":"gcp-f0163","card":"q-gcp-038-exercise-07-02-daily-subscriber-emails","sec":"gcp-s035","q":"What does the <code>/generate-morning-email-tasks</code> handler do?","a":"<p>It gets the filtered users and creates one send-email task per user.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>app.post(&#x27;/generate-morning-email-tasks&#x27;, async (req, res) =&gt; {\n  const emails = await dbService.getFilteredUsersForMorningEmail();\n  for (var i = 0; i &lt; emails.length; i++) {\n    await createTask(senderTaskQueueName, { email: emails[i], subject, emailBody }, &#x27;/send-email&#x27;);\n  }\n  res.status(200).send(&#x27;Emails sent&#x27;).end();\n});</code></pre></div>","hand":true},{"id":"gcp-f0164","card":"q-gcp-039-9-operations-tools-logging-debugger-trac","sec":"gcp-s036","q":"What do Cloud Logging, Cloud Debugger and Cloud Trace do and how are they set up?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Tool</th><th>Purpose</th><th>Setup</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Cloud Logging</strong></td><td>View application logs</td><td>Automatic with <code>console.log()</code> on App Engine</td></tr>\n      <tr><td><strong>Cloud Debugger</strong></td><td>Inspect variables of a running app</td><td><code>@google-cloud/debug-agent</code></td></tr>\n      <tr><td><strong>Cloud Trace</strong></td><td>Find latency bottlenecks</td><td><code>@google-cloud/trace-agent</code></td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0165","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"What does Cloud Logging collect and which services are auto-collected?","a":"<p>It collects logs from all systems and apps. Logs are <strong>auto-collected</strong> for App Engine, GKE, Cloud Run and Cloud Functions.</p>","hand":true},{"id":"gcp-f0166","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"What other ways can logs get into Cloud Logging?","a":"<p>The <strong>Logging Agent</strong> (Compute Engine or AWS EC2), <strong>logging libraries</strong> (apps elsewhere), the <strong>Logging API</strong> (REST), and the <strong>gcloud CLI</strong>.</p>","hand":true},{"id":"gcp-f0167","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"How do Node.js logs reach Cloud Logging on App Engine?","a":"<p><code>console.log()</code> is captured automatically. Libraries such as Winston or Bunyan also work.</p>","hand":true},{"id":"gcp-f0168","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"Which gcloud commands write a simple and a structured JSON log entry?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud logging write &lt;log-name&gt; &quot;A simple entry.&quot;\ngcloud logging write --payload-type=json &lt;log-name&gt; &#x27;{&quot;message&quot;: &quot;My second entry&quot;, &quot;weather&quot;: &quot;partly cloudy&quot;}&#x27;</code></pre></div>","hand":true},{"id":"gcp-f0169","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"Which gcloud command reads logs of resource type global?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>gcloud logging read &quot;resource.type=global&quot;</code></pre></div>","hand":true},{"id":"gcp-f0170","card":"q-gcp-040-cloud-logging","sec":"gcp-s037","q":"What does the Exercise 08_01 route <code>/create_a_log</code> do?","a":"<p>It writes a log with <code>console.log</code> and returns \"A log has been written.\"</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>app.get(&#x27;/create_a_log&#x27;, async (req, res) =&gt; {\n  console.log(&#x27;Hello cloud logging!&#x27;);\n  res.status(200).send(&#x27;A log has been written.&#x27;).end();\n});</code></pre></div>","hand":true},{"id":"gcp-f0171","card":"q-gcp-041-logs-viewer","sec":"gcp-s038","q":"What can you do with a log entry in the Logs Viewer?","a":"<p>Each row is a log entry. Expand it, expand nested fields, copy to the clipboard, or add a field to the summary line to spot patterns.</p>","hand":true},{"id":"gcp-f0172","card":"q-gcp-041-logs-viewer","sec":"gcp-s038","q":"What are the Logs Viewer tools?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Tool</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td>Query Builder</td><td>Build queries (resource type, severity), then Run Query</td></tr>\n      <tr><td>Time filter</td><td>Restrict range (e.g. past 6 hours)</td></tr>\n      <tr><td>Histogram</td><td>Log frequency over time; click a bar, Jump to time</td></tr>\n      <tr><td>Logs Field Explorer</td><td>Field summary and counts; click a value (e.g. <code>error</code>) to filter</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"gcp-f0173","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"What is Cloud Debugger and where does it work?","a":"<p>It takes snapshots and inspects variable state on <strong>live traffic</strong>, useful for bugs that are hard to reproduce locally. It works with App Engine, Compute Engine, GKE, Cloud Run and VMs elsewhere.</p>","hand":true},{"id":"gcp-f0174","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"How do you set up Cloud Debugger in the console?","a":"<p>Open Debugger, make sure the version with 100% traffic is selected, pick the file, and press Check to sync and activate.</p>","hand":true},{"id":"gcp-f0175","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"What is a Cloud Debugger snapshot?","a":"<p>Click a line number. On the next request it captures the <strong>call stack and variable values</strong>. It supports <strong>conditions</strong> (e.g. <code>i === 1</code> for the second loop pass) and <strong>expressions</strong> (e.g. <code>helloArray[i]</code>).</p>","hand":true},{"id":"gcp-f0176","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"What is a Cloud Debugger logpoint?","a":"<p>It adds logs to the running app <strong>without changing source or redeploying</strong>. Pick a line, give a <strong>condition</strong> (e.g. <code>true</code>) and a <strong>log message</strong> with <code>{expression}</code> syntax (e.g. <code>\"value of response is {response}\"</code>).</p>","hand":true},{"id":"gcp-f0177","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"How do you start the Cloud Debugger agent in a Node.js app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>require(&#x27;@google-cloud/debug-agent&#x27;).start({\n  serviceContext: { enableCanary: false },\n  allowExpressions: true\n});</code></pre></div>","hand":true},{"id":"gcp-f0178","card":"q-gcp-042-cloud-debugger-exercise-08-03","sec":"gcp-s039","q":"What is the debug exercise route that builds a response in a loop?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>app.get(&#x27;/&#x27;, async (req, res) =&gt; {\n  let response = &#x27;&#x27;;\n  const helloArray = [&#x27;H&#x27;, &#x27;e&#x27;, &#x27;l&#x27;, &#x27;l&#x27;, &#x27;o&#x27;, &#x27;!&#x27;];\n  for (let i = 0; i &lt; helloArray.length; i++) {\n    response += helloArray[i];\n  }\n  res.status(200).send(response).end();\n});</code></pre></div>","hand":true},{"id":"gcp-f0179","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"What does Cloud Trace do and where does it work?","a":"<p>It traces requests to find bottlenecks. It samples a <strong>subset</strong> of requests. It works out of the box on App Engine and can be set up elsewhere, even outside GCP.</p>","hand":true},{"id":"gcp-f0180","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"What does the Cloud Trace overview page show?","a":"<p>Insights (improvement tips), Recent Traces, Most Frequent URIs (keep latency low on these), Most Frequent RPCs, Chargeable Trace Spans (free tier: first <strong>2.5 million</strong> spans), and Daily Analysis Reports (latency vs previous week).</p>","hand":true},{"id":"gcp-f0181","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"What is the free tier of Cloud Trace?","a":"<p>The first <strong>2.5 million</strong> spans.</p>","hand":true},{"id":"gcp-f0182","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"What does the Cloud Trace list let you do?","a":"<p>Filter by time range, minimum latency, status and version. Each trace shows <strong>spans</strong>, which show which part of the code took longest, and links to the full log entry in the Logging Viewer.</p>","hand":true},{"id":"gcp-f0183","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"How are Cloud Trace reports created?","a":"<p>Daily analysis reports are automatic. Custom reports are made with Create a Report.</p>","hand":true},{"id":"gcp-f0184","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"How do you start the Cloud Trace agent in a Node.js app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>require(&#x27;@google-cloud/trace-agent&#x27;).start();</code></pre></div>","hand":true},{"id":"gcp-f0185","card":"q-gcp-043-cloud-trace-exercise-08-04","sec":"gcp-s040","q":"What does the slow trace exercise endpoint do?","a":"<p><code>/a_weird_endpoint</code> loops 10 times, sleeps 1500 ms and requests data from example.com with axios each time.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>app.get(&#x27;/a_weird_endpoint&#x27;, async (req, res) =&gt; {\n  for (let i = 0; i &lt; 10; i++) {\n    await sleep(1500);</code></pre></div>","hand":true},{"id":"gcp-f0186","card":"q-gcp-044-10-next-steps","sec":"gcp-s041","q":"What are the suggested next steps after the GCP course?","a":"<p>Explore <strong>Cloud Firestore</strong> (scalable NoSQL, GCP-only) and <strong>Firebase</strong> (zero back-end apps).</p>","hand":true}];
